`csvclean.py` — def clean(rows: list[list[Any]]) -> list[dict[str, Any]]:

Turn a header row plus data rows into coerced, normalised dictionaries.

def clean(rows: list[list[Any]]) -> list[dict[str, Any]]:
    """Turn a header row plus data rows into coerced, normalised dictionaries."""
    if not rows:
        return []
    headers = normalise_headers([str(cell) for cell in rows[0]])
    width = len(headers)
    cleaned: list[dict[str, Any]] = []
    for row in rows[1:]:
        repaired = repair_row(row, width)
        cleaned.append(
            {header: coerce(cell) for header, cell in zip(headers, repaired, strict=True)}
        )
    return cleaned

`csvclean.py` — def coerce(value: Any) -> Any:

Coerce a cell to int, float, bool or None, leaving anything else as text.

def coerce(value: Any) -> Any:
    """Coerce a cell to int, float, bool or None, leaving anything else as text."""
    if value is None:
        return None
    if isinstance(value, bool | int | float):
        return value
    text = value.strip()
    if text.lower() in NULL_WORDS:
        return None
    if text.lower() in TRUE_WORDS:
        return True
    if text.lower() in FALSE_WORDS:
        return False
    if INTEGER.match(text):
        return int(text)
    if DECIMAL.match(text):
        return float(text)
    return text

`csvclean.py` — def column_types(rows: list[dict[str, Any]]) -> dict[str, str]:

The single type name of each column, or `mixed` where values disagree.

Columns that are entirely null report `null`.

def column_types(rows: list[dict[str, Any]]) -> dict[str, str]:
    """The single type name of each column, or `mixed` where values disagree.

    Columns that are entirely null report `null`.
    """
    types: dict[str, set[str]] = {}
    for row in rows:
        for key, value in row.items():
            name = "null" if value is None else type(value).__name__
            types.setdefault(key, set()).add(name)
    resolved: dict[str, str] = {}
    for key, names in types.items():
        concrete = names - {"null"}
        if not concrete:
            resolved[key] = "null"
        elif len(concrete) == 1:
            resolved[key] = concrete.pop()
        else:
            resolved[key] = "mixed"
    return resolved

`intervals.py` — def merge(intervals: list[Interval]) -> list[Interval]:

Merge overlapping and adjacent intervals into a sorted, disjoint list.

def merge(intervals: list[Interval]) -> list[Interval]:
    """Merge overlapping and adjacent intervals into a sorted, disjoint list."""
    if not intervals:
        return []
    ordered = sorted(normalise(interval) for interval in intervals)
    merged: list[Interval] = [ordered[0]]
    for start, end in ordered[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end + 1:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

`parsing.py` — def format_duration(seconds: int) -> str:

Render whole seconds back into the compact form `parse_duration` accepts.

def format_duration(seconds: int) -> str:
    """Render whole seconds back into the compact form `parse_duration` accepts."""
    if seconds < 0:
        raise ParseError("duration must not be negative")
    if seconds == 0:
        return "0s"
    parts: list[str] = []
    remaining = seconds
    for unit, size in DURATION_UNITS.items():
        count, remaining = divmod(remaining, size)
        if count:
            parts.append(f"{count}{unit}")
    return "".join(parts)

`parsing.py` — def parse_date(text: str) -> date:

Parse a date in any supported format, or raise ParseError naming the input.

def parse_date(text: str) -> date:
    """Parse a date in any supported format, or raise ParseError naming the input."""
    from datetime import datetime

    candidate = text.strip()
    if not candidate:
        raise ParseError("empty date")
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(candidate, fmt).date()
        except ValueError:
            continue
    raise ParseError(f"unrecognised date: {text!r}")

`parsing.py` — def parse_duration(text: str) -> int:

Parse `1h30m`, `90s`, `2d` into whole seconds.

Units are weeks, days, hours, minutes and seconds. A bare number is seconds.

def parse_duration(text: str) -> int:
    """Parse `1h30m`, `90s`, `2d` into whole seconds.

    Units are weeks, days, hours, minutes and seconds. A bare number is seconds.
    """
    candidate = text.strip().lower()
    if not candidate:
        raise ParseError("empty duration")
    if candidate.isdigit():
        return int(candidate)
    terms = DURATION_TERM.findall(candidate)
    if not terms:
        raise ParseError(f"unrecognised duration: {text!r}")
    consumed = sum(len(amount) + len(unit) for amount, unit in terms)
    if consumed != len(candidate.replace(" ", "")):
        raise ParseError(f"unrecognised duration: {text!r}")
    total = 0
    for amount, unit in terms:
        if unit not in DURATION_UNITS:
            raise ParseError(f"unknown duration unit: {unit!r}")
        total += int(amount) * DURATION_UNITS[unit]
    return total

`ratelimit.py` — def consume(bucket: Bucket, now: float, cost: float = 1.0) -> tuple[Bucket, bool]:

Try to spend `cost` tokens. Returns the new bucket and whether it was allowed.

def consume(bucket: Bucket, now: float, cost: float = 1.0) -> tuple[Bucket, bool]:
    """Try to spend `cost` tokens. Returns the new bucket and whether it was allowed."""
    if cost <= 0:
        raise ValueError("cost must be positive")
    if cost > bucket.capacity:
        raise ValueError("cost exceeds the bucket's capacity and can never be served")
    filled = refill(bucket, now)
    if filled.tokens >= cost:
        return replace(filled, tokens=filled.tokens - cost), True
    return filled, False

`ratelimit.py` — def refill(bucket: Bucket, now: float) -> Bucket:

Advance the bucket to `now`. Time never runs backwards.

def refill(bucket: Bucket, now: float) -> Bucket:
    """Advance the bucket to `now`. Time never runs backwards."""
    if now < bucket.updated_at:
        raise ValueError("now must not precede the bucket's last update")
    elapsed = now - bucket.updated_at
    gained = elapsed * bucket.refill_per_second
    tokens = bucket.tokens + gained
    if tokens > bucket.capacity:
        tokens = bucket.capacity
    return replace(bucket, tokens=tokens, updated_at=now)

`ratelimit.py` — def time_until(bucket: Bucket, now: float, cost: float = 1.0) -> float:

Seconds until `cost` tokens are available. Zero when they already are.

def time_until(bucket: Bucket, now: float, cost: float = 1.0) -> float:
    """Seconds until `cost` tokens are available. Zero when they already are."""
    if cost <= 0:
        raise ValueError("cost must be positive")
    if cost > bucket.capacity:
        raise ValueError("cost exceeds the bucket's capacity and can never be served")
    filled = refill(bucket, now)
    if filled.tokens >= cost:
        return 0.0
    if filled.refill_per_second == 0:
        return float("inf")
    return (cost - filled.tokens) / filled.refill_per_second

`retry.py` — def backoff_delay(attempt: int, base: float = 0.5, factor: float = 2.0, cap: float = 30.0) -> float:

Delay before retry number `attempt`, one-based, capped at `cap`.

def backoff_delay(
    attempt: int,
    base: float = 0.5,
    factor: float = 2.0,
    cap: float = 30.0,
) -> float:
    """Delay before retry number `attempt`, one-based, capped at `cap`."""
    if attempt < 1:
        raise ValueError("attempt must be at least 1")
    if base <= 0:
        raise ValueError("base must be positive")
    if factor < 1:
        raise ValueError("factor must be at least 1")
    delay = base * (factor ** (attempt - 1))
    if delay > cap:
        return cap
    return delay

`retry.py` — def jittered(delay: float, ratio: float, seed: float) -> float:

Deterministic jitter in `[delay * (1 - ratio), delay * (1 + ratio)]`.

`seed` is a caller-supplied value in `[0, 1)`; nothing here is random.

def jittered(delay: float, ratio: float, seed: float) -> float:
    """Deterministic jitter in `[delay * (1 - ratio), delay * (1 + ratio)]`.

    `seed` is a caller-supplied value in `[0, 1)`; nothing here is random.
    """
    if not 0.0 <= ratio <= 1.0:
        raise ValueError("ratio must be between 0 and 1")
    if not 0.0 <= seed < 1.0:
        raise ValueError("seed must be in [0, 1)")
    spread = delay * ratio
    return delay - spread + (2 * spread * seed)

`slugs.py` — def unique_slug(text: str, taken: set[str], max_length: int = 60) -> str:

Slugify, appending -2, -3, ... until the result is not already in `taken`.

def unique_slug(text: str, taken: set[str], max_length: int = 60) -> str:
    """Slugify, appending -2, -3, ... until the result is not already in `taken`."""
    base = slugify(text, max_length)
    if not base:
        base = FALLBACK
    if base not in taken:
        return base
    suffix = 2
    while True:
        candidate = _suffixed(base, suffix, max_length)
        if candidate not in taken:
            return candidate
        suffix += 1

`tabular.py` — def _apply(name: str, values: list[Any], places: int) -> Any:

def _apply(name: str, values: list[Any], places: int) -> Any:
    if name == "count":
        return len([value for value in values if value is not None])
    if name == "first":
        return values[0] if values else None
    if name == "last":
        return values[-1] if values else None
    numbers = _numeric(values)
    if not numbers:
        return None
    if name == "sum":
        return round(sum(numbers), places)
    if name == "mean":
        return round(sum(numbers) / len(numbers), places)
    if name == "min":
        return min(numbers)
    if name == "max":
        return max(numbers)
    raise ValueError(f"unknown aggregation: {name!r}")

